-- Preserve Workspace 2.0 product definitions in all future menu-scope evidence.
-- Existing snapshots remain immutable; no menu identity or ingredient is rewritten.
DROP TRIGGER menu_scope_notebooks_insert;
CREATE TRIGGER menu_scope_notebooks_insert AFTER INSERT ON notebooks WHEN json_valid(NEW.payload) BEGIN INSERT INTO menu_scope_sources(notebook_revision,notebook_payload,review_payload,recorded_at,actor) SELECT n.revision,json_object('schemaVersion',json_extract(n.payload,'$.schemaVersion'),'reviewSourceRevision',json_extract(n.payload,'$.reviewSourceRevision'),'workspaceRecipes',json(coalesce(json_extract(n.payload,'$.workspaceRecipes'),'[]')),'dishes',json(json_extract(n.payload,'$.dishes')),'recipes',json(json_extract(n.payload,'$.recipes')),'processes',json(coalesce(json_extract(n.payload,'$.processes'),'[]')),'items',json((SELECT json_group_array(json_object('id',json_extract(i.value,'$.id'),'name',json_extract(i.value,'$.name'),'kind',json_extract(i.value,'$.kind'),'aliases',json(coalesce(json_extract(i.value,'$.aliases'),'[]')),'inputs',json(coalesce(json_extract(i.value,'$.inputs'),'[]')),'externalUse',json_extract(i.value,'$.externalUse'))) FROM json_each(n.payload,'$.items') i))),(SELECT json_group_array(json(payload)) FROM reviewed_entities WHERE review_id='vinohrady-cleanup-2026-09'),n.updated_at,n.updated_by FROM notebooks n WHERE n.id='kitchen' AND json_valid(n.payload); END;
